import java.util.Scanner;
class ManagerEmployee { private int id; private String name,department; protected double salary; ManagerEmployee(int i,String n,String d,double s){id=i;name=n;department=d;salary=s;} void show(){System.out.println("ID: "+id+" Name: "+name+" Department: "+department+" Salary: "+salary);} }
public class Manager extends ManagerEmployee { private double bonus; Manager(int i,String n,String d,double s,double b){super(i,n,d,s);bonus=b;} void showManager(){show();System.out.println("Bonus: "+bonus+" Total salary: "+(salary+bonus));} public static void main(String[] a){Scanner s=new Scanner(System.in);System.out.print("ID: ");int i=s.nextInt();s.nextLine();System.out.print("Name: ");String n=s.nextLine();System.out.print("Department: ");String d=s.nextLine();System.out.print("Salary: ");double pay=s.nextDouble();System.out.print("Bonus: ");double b=s.nextDouble();new Manager(i,n,d,pay,b).showManager();s.close();} }
